import { LaidOutDiagram } from '@archeglyph/core/layout/laid_out_diagram';
import { LaidOutGroup } from '@archeglyph/core/layout/laid_out_group';
import {
  ElementStyleChange,
  ElementStyleEntry,
  ElementStyleEntrySchema,
  StyleEdit,
  StyleEditSchema,
  Stylesheet,
  Vec2,
  Vec2Schema
} from '@archeglyph/proto/gen/style_pb';
import { create } from '@bufbuild/protobuf';
import { elementChange, styleEdit } from './edit_builder';
import { initOf, patchGroupEntry, patchNodeEntry } from './entry_patch';
import { ElementMove } from './move';

/**
 * Which path unpinning clears. `layout` whole when position was all it held,
 * so an emptied layout does not linger; otherwise just the position.
 */
function nodePositionPath(existing: ElementStyleEntry | undefined): ReadonlyArray<string> {
  const layout = existing?.layout;
  const keepsLayout = layout !== undefined
    && (layout.size !== undefined || layout.rotation !== undefined);
  return [keepsLayout ? 'layout.position' : 'layout'];
}

function groupPositionPath(existing: ElementStyleEntry | undefined): ReadonlyArray<string> {
  const layout = existing?.boxLayout;
  const keepsLayout = layout !== undefined
    && (layout.size !== undefined || layout.padding !== undefined
      || layout.labelPosition !== undefined);
  return [keepsLayout ? 'boxLayout.position' : 'boxLayout'];
}

export function unpinAllEdit(stylesheet: Stylesheet): StyleEdit {
  // One entry holds both forms, so each element clears the position of both.
  return styleEdit({
    elementChanges: Object.keys(stylesheet.elements).map((elementId) =>
      elementChange(elementId, create(ElementStyleEntrySchema, {}), [
        ...nodePositionPath(stylesheet.elements[elementId]),
        ...groupPositionPath(stylesheet.elements[elementId]),
      ])),
    description: 'Unpin all nodes and groups',
  });
}

export function unpinElementsEdit(stylesheet: Stylesheet, refs: Array<ElementMove>): StyleEdit {
  const nodeIds = refs.filter((ref) => ref.kind === 'node').map((ref) => ref.id);
  const groupIds = refs.filter((ref) => ref.kind === 'group').map((ref) => ref.id);
  // Annotations are always explicitly positioned (design.md) -- there is no
  // auto-layout for them to fall back to, so unpinning one would mean losing
  // its position with nothing to replace it. Skipped rather than rejected, so
  // a mixed selection still unpins the parts that can be.
  return styleEdit({
    elementChanges: [
      ...nodeIds.map((nodeId) =>
        elementChange(nodeId, create(ElementStyleEntrySchema, {}), nodePositionPath(stylesheet.elements[nodeId]))),
      ...groupIds.map((groupId) =>
        elementChange(groupId, create(ElementStyleEntrySchema, {}), groupPositionPath(stylesheet.elements[groupId]))),
    ],
    description: 'Unpin selection',
  });
}

/**
 * Parent-relative position for an element the layout placed at `position`.
 *
 * Layout coordinates are canvas-absolute while style positions are relative
 * to the immediate parent group, so every pin has to be converted back before
 * it is written to the stylesheet.
 */
function parentRelative(
  groupsById: Record<string, { position: { x: number; y: number } }>,
  position: { x: number; y: number },
  parentId: string | undefined,
): Vec2 {
  const parent = parentId === undefined ? undefined : groupsById[parentId];
  return parent === undefined
    ? create(Vec2Schema, { x: position.x, y: position.y })
    : create(Vec2Schema, {
        x: position.x - parent.position.x,
        y: position.y - parent.position.y,
      });
}

/**
 * Pin a group where the layout put it. A closed container is drawn as a block
 * and is pinned through its block layout; an open one through its box layout.
 */
function pinGroup(
  stylesheet: Stylesheet,
  diagram: LaidOutDiagram,
  group: LaidOutGroup,
): ElementStyleChange {
  const position = parentRelative(diagram.groups, group.position, group.parentGroup);
  const existing = stylesheet.elements[group.id];
  return elementChange(
    group.id,
    group.isSuperNode ? patchNodeEntry(existing, { position }) : patchGroupEntry(existing, { position }),
  );
}

export function pinAllEdit(stylesheet: Stylesheet, diagram: LaidOutDiagram): StyleEdit {
  const nodeChanges = Object.values(diagram.nodes).map((node) =>
    elementChange(
      node.id,
      patchNodeEntry(stylesheet.elements[node.id], {
        position: parentRelative(diagram.groups, node.position, node.parentGroup),
      }),
    ),
  );
  const groupChanges = Object.values(diagram.groups).map((group) =>
    pinGroup(stylesheet, diagram, group),
  );

  return styleEdit({
    elementChanges: [...nodeChanges, ...groupChanges],
    description: 'Pin all laid-out elements',
  });
}

/**
 * `edit` with a position written for every node and group that does not have
 * one yet, taken from where the layout currently puts them.
 *
 * This is pin-on-touch (editor-ui-review.md §5.2). A diagram with no explicit
 * positions is arranged by ELK; the moment one element gets a position, the
 * layout engine stops calling ELK for placement and seeds the rest beside the
 * pinned one instead -- so moving a single node would rearrange the whole
 * diagram. Materializing the current arrangement into the SAME edit keeps
 * everything else exactly where the user sees it, and keeps it to one undo
 * entry.
 *
 * The materialized changes come FIRST so the caller's own changes win for any
 * element they also touch: applyMapChanges merges each change over the one
 * before it, so a field the caller names beats the materialized position while
 * a field it leaves alone still gets pinned.
 *
 * Elements already carrying a position in the stylesheet are skipped, so this
 * is a no-op from the second gesture onwards.
 */
export function withLayoutMaterialized(
  stylesheet: Stylesheet,
  diagram: LaidOutDiagram,
  edit: StyleEdit,
): StyleEdit {
  const nodePins: Array<ElementStyleChange> = Object.values(diagram.nodes)
    .filter((node) => stylesheet.elements[node.id]?.layout?.position === undefined)
    .map((node) =>
      elementChange(
        node.id,
        patchNodeEntry(stylesheet.elements[node.id], {
          position: parentRelative(diagram.groups, node.position, node.parentGroup),
        }),
      ),
    );
  const groupPins: Array<ElementStyleChange> = Object.values(diagram.groups)
    .filter((group) => {
      const entry = stylesheet.elements[group.id];
      const pinned = group.isSuperNode ? entry?.layout?.position : entry?.boxLayout?.position;
      return pinned === undefined;
    })
    .map((group) => pinGroup(stylesheet, diagram, group));

  if (nodePins.length === 0 && groupPins.length === 0) {
    return edit;
  }

  return create(StyleEditSchema, {
    ...initOf(edit),
    elementChanges: [...nodePins, ...groupPins, ...edit.elementChanges],
  });
}
